python3 -c "
import subprocess, re

result = subprocess.run(['llvm-objdump-18', '--syms', '/tmp/libcoreclr.dwarf'], capture_output=True, text=True)
symbols = []
for line in result.stdout.split('\n'):
    m = re.match(r'^([0-9a-f]+)\s+.*\s+(\S+)$', line)
    if m:
        addr = int(m.group(1), 16)
        name = m.group(2)
        symbols.append((addr, name))

symbols.sort()

targets = [0x3e1700, 0x2615fc, 0x16c31c, 0x16c620, 0x18b678, 0x49cc]
for target in targets:
    best = None
    for addr, name in symbols:
        if addr <= target:
            best = (addr, name)
        else:
            break
    if best:
        print(f'  0x{target:x} -> {best[1]} + 0x{target - best[0]:x}')
    else:
        print(f'  0x{target:x} -> (unknown)')
" 2>&1

